From 6ddaf9d016140f9380de3542eef21aba3335d39c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:19:57 +0100
Subject: [PATCH] volumemonitor: don't wake up devices, reuse streams still
 connecting

The meter streams kept suspended devices awake. Not inhibiting suspend
leaked them, as they only connect once their device wakes, so keep the
dropped ones and let the next meter of that device reuse them instead.

BUG: 507212
---
 src/volumemonitor.cpp | 34 +++++++++++++++++++++++++++++++---
 src/volumemonitor.h   |  1 +
 2 files changed, 32 insertions(+), 3 deletions(-)

diff --git a/src/volumemonitor.cpp b/src/volumemonitor.cpp
index 27d6d828..ff9b356a 100644
--- a/src/volumemonitor.cpp
+++ b/src/volumemonitor.cpp
@@ -19,6 +19,13 @@

 using namespace PulseAudioQt;

+namespace
+{
+// Streams that don't inhibit auto suspend only finish connecting once their device wakes up. Keep the ones dropped
+// while still connecting, so the next monitor of the same device reuses them instead of piling up new ones.
+QHash<std::pair<uint32_t, uint32_t>, pa_stream *> s_connectingStreams;
+}
+
 VolumeMonitor::VolumeMonitor(QObject *parent)
     : QObject(parent)
 {
@@ -65,13 +72,25 @@ void PulseAudioQt::VolumeMonitor::setTarget(PulseAudioQt::VolumeObject *target)
                 [](pa_stream *s, void *) {
                     pa_stream_disconnect(s);
                     pa_stream_set_state_callback(s, nullptr, nullptr);
+                    for (auto it = s_connectingStreams.begin(); it != s_connectingStreams.end(); ++it) {
+                        if (it.value() == s) {
+                            s_connectingStreams.erase(it);
+                            pa_stream_unref(s);
+                            break;
+                        }
+                    }
                 },
                 nullptr);
+            if (!s_connectingStreams.contains(m_streamKey)) {
+                s_connectingStreams.insert(m_streamKey, std::exchange(m_stream, nullptr));
+            }
         } else {
             pa_stream_disconnect(m_stream);
         }
-        pa_stream_unref(m_stream);
-        m_stream = nullptr;
+        if (m_stream) {
+            pa_stream_unref(m_stream);
+            m_stream = nullptr;
+        }
         Q_EMIT availableChanged();
     }

@@ -138,6 +157,15 @@ void VolumeMonitor::createStream()
         return;
     }

+    m_streamKey = {sourceIdx, streamIdx};
+    if ((m_stream = s_connectingStreams.take(m_streamKey))) {
+        pa_stream_set_state_callback(m_stream, nullptr, nullptr);
+        pa_stream_set_read_callback(m_stream, read_callback, this);
+        pa_stream_set_suspended_callback(m_stream, suspended_callback, this);
+        Q_EMIT availableChanged();
+        return;
+    }
+
     if (!(m_stream = pa_stream_new(context, "PlasmaPA-VolumeMeter", &ss, nullptr))) {
         qCWarning(PLASMAPA) << "Failed to create stream";
         return;
@@ -150,7 +178,7 @@ void VolumeMonitor::createStream()
     pa_stream_set_read_callback(m_stream, read_callback, this);
     pa_stream_set_suspended_callback(m_stream, suspended_callback, this);

-    flags = (pa_stream_flags_t)(PA_STREAM_DONT_MOVE | PA_STREAM_PEAK_DETECT | PA_STREAM_ADJUST_LATENCY);
+    flags = (pa_stream_flags_t)(PA_STREAM_DONT_MOVE | PA_STREAM_PEAK_DETECT | PA_STREAM_ADJUST_LATENCY | PA_STREAM_DONT_INHIBIT_AUTO_SUSPEND);

     if (pa_stream_connect_record(m_stream, t, &attr, flags) < 0) {
         pa_stream_unref(m_stream);
diff --git a/src/volumemonitor.h b/src/volumemonitor.h
index 28a7671e..2e2145d3 100644
--- a/src/volumemonitor.h
+++ b/src/volumemonitor.h
@@ -63,6 +63,7 @@ private:

     VolumeObject *m_target = nullptr;
     pa_stream *m_stream = nullptr;
+    std::pair<uint32_t, uint32_t> m_streamKey;

     qreal m_volume = 0;
 };
